{
  "headline": "Prioritize indoor air and mask up for outdoor travel",
  "summary": "Gurugram is at {{level.name}} with AQI {{aqi.now}}. Indoor filtration can reduce your exposure by {{impact.diy_box_fan_filter.pct}} and the best outdoor air is between {{best.start}} and {{best.end}}.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Build a DIY box fan air filter",
      "why": "A simple box fan filter can significantly reduce indoor PM2.5, offering up to {{impact.diy_box_fan_filter.pct}} cleaner air.",
      "when": "Run it continuously, especially when outdoor air quality is poor.",
      "steps": [
        "Attach a MERV-13 filter to the back of a box fan.",
        "Seal the edges with tape.",
        "Place in the room where you spend the most time."
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Wear an N95 mask during open transport",
      "why": "An N95 mask provides excellent protection against PM2.5, reducing your exposure by {{impact.n95_for_open_transport.pct}} on public transport or during commutes.",
      "when": "Always wear when using buses, trains, or any open-air transit.",
      "steps": [
        "Ensure the mask has a snug fit around your face.",
        "Avoid touching the mask while wearing it."
      ]
    },
    {
      "actionId": "exercise_indoors_when_poor",
      "title": "Move exercise indoors when air quality is poor",
      "why": "Exercising outdoors during high pollution can increase particle intake significantly. Indoor exercise avoids this, reducing exposure by {{impact.exercise_indoors_when_poor.pct}}.",
      "when": "Whenever the air quality is {{level.name}} or worse.",
      "steps": [
        "Opt for home workouts, yoga, or gym visits with good ventilation.",
        "Consider using an air purifier in your exercise space."
      ]
    },
    {
      "actionId": "air_house_in_best_window",
      "title": "Ventilate your home during cleaner air windows",
      "why": "Opening windows during the best air quality window ({{best.start}} to {{best.end}}) can improve indoor air freshness with minimal pollution intake, reducing exposure by {{impact.air_house_in_best_window.pct}}.",
      "when": "Only open windows when outdoor air is at its cleanest.",
      "steps": [
        "Check the air quality forecast before opening windows.",
        "Close windows before pollution levels rise."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for no-burning policies in your community",
      "why": "Community-wide efforts to reduce burning can lead to widespread air quality improvements.",
      "when": "Discuss at your next Resident Welfare Association meeting.",
      "steps": [
        "Share information about the health impacts of burning.",
        "Encourage alternative heating and waste disposal methods."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Limit outdoor playtime when air quality is {{level.name}}."
    },
    {
      "group": "respiratory",
      "note": "Keep your rescue inhaler accessible and avoid strenuous outdoor activities."
    }
  ],
  "tradeoffs": [
    "Wearing an N95 mask on public transport is recommended to mitigate increased exposure risk."
  ]
}
